#!/usr/bin/env bash
# Assemble the CN endsem prep files from the _parts fragments.
set -euo pipefail

BASE="/home/nithilan/Projects/amrita-labs/5/computer-networks/endsem"
cd "$BASE/_parts"

need() { [ -f "$1" ] || { echo "missing fragment: $1" >&2; exit 1; }; }

# the paper bank is regenerated by fix_pyq.py so its numbering cannot drift
python3 "$BASE/fix_pyq.py"

section() { printf '\n%s\n\n' "$1" >> "$out"; }

# ---------- prep file ----------
out="$BASE/CN-endsem-prep.org"
: > "$out"

need 00-front.org
cat 00-front.org >> "$out"

section '* CO1 — Architecture, delays, and layering'
need 01-co1.org
cat 01-co1.org >> "$out"

section '* CO2 — Application layer, and CO6 cloud'
need 02-co2.org
cat 02-co2.org >> "$out"

section '* CO3 — Transport layer'
need 03-transport.org
cat 03-transport.org >> "$out"
need 03b-rdt.org
cat 03b-rdt.org >> "$out"

section '* CO4 — Network layer and routing'
need 04-network.org
cat 04-network.org >> "$out"
need 05-routing.org
cat 05-routing.org >> "$out"

section '* CO5 — Link layer and LANs'
need 06-link.org
cat 06-link.org >> "$out"

section '* The paper bank'
need 90-pyq.org
cat 90-pyq.org >> "$out"

# ---------- answers file ----------
aout="$BASE/CN-endsem-answers.org"
{
  printf '#+TITLE: CN endsem — model answers\n'
  printf '#+SUBTITLE: Open only after you have written an attempt\n'
  printf '#+STARTUP: overview\n'
  printf '#+OPTIONS: toc:2 num:nil\n\n'
  printf '* Read this first\n\n'
  printf 'Every answer below is written the way the marking scheme wants it.\n'
  printf 'Each one ends with a =MARKS:= line that shows where the marks sit, and\n'
  printf 'a =WATCH:= line that names the mistake which loses them.\n\n'
  printf 'Mark your own attempt before you read the model. Score each question out\n'
  printf 'of its full marks, then add up. A score below half means the topic needs\n'
  printf 'another pass in the notes. A score above three quarters means move on.\n'
} > "$aout"

for f in 91-answers-CNE1.org 92-answers-CNE2-CNE3.org 93-answers-CNE5.org 94-answers-CNE4-CNE6.org; do
  if [ -f "$f" ]; then
    printf '\n' >> "$aout"
    python3 "$BASE/normalize_answers.py" "$f" >> "$aout"
  else
    printf '\n* %s\n\nNot written yet.\n' "$f" >> "$aout"
  fi
done

printf 'prep    %s  %s lines\n' "$out" "$(wc -l < "$out")"
printf 'answers %s  %s lines\n' "$aout" "$(wc -l < "$aout")"

# align every org table so the plain text stays readable
for f in "$out" "$aout"; do
  emacs -Q --batch "$f" \
    --eval '(progn (org-mode) (org-table-map-tables (lambda () (org-table-align))) (save-buffer))' \
    >/dev/null 2>&1 || echo "table align skipped for $f" >&2
done
printf 'tables aligned\n'
